import { z } from 'zod';

/**
 * Every API route is served under this prefix. CloudFront forwards `/api/*` to the ALB unchanged
 * (infra `PATHS.api`), the ALB health check is `/api/health`, and the WAF rules match
 * `/api/s/...`. So the API mounts globally at `/api` (NestJS `app.setGlobalPrefix('api')`) and
 * route paths in the route table are relative to it.
 */
export const API_PREFIX = '/api';

/** Row ids are uuids (uuidv7, generated by PostgreSQL). */
export const idSchema = z.uuid();

/** Timestamps in responses: ISO 8601 with offset, e.g. `2026-10-25T05:12:31.123Z`. */
export const isoDateTimeSchema = z.iso.datetime({ offset: true });

/** A byte count. Every byte count fits a JavaScript number exactly (below 2^53). */
export const byteCountSchema = z.number().int().nonnegative().max(Number.MAX_SAFE_INTEGER);

/**
 * A short-lived CloudFront signed URL the API puts in a response (thumbnails, previews,
 * downloads). Never an S3 URL; presigned S3 part URLs for uploads are the only exception.
 */
export const signedUrlSchema = z.url();

/** `:id` route params that must be a uuid. */
export const idParamsSchema = z.object({ id: idSchema });
